namespace sv_7e2d95a6516c4ccface21825bec27c1c.Services;

/// <summary>
/// Scoped service (per-circuit in Blazor Server) that holds the current warehouse
/// selection and low-stock alert count. Provides change-notification events so
/// unrelated components can stay synchronized without parent-child parameter passing.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";
    private int _lowStockAlertCount;

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyWarehouseChanged();
        }
    }

    public int LowStockAlertCount
    {
        get => _lowStockAlertCount;
        set
        {
            if (_lowStockAlertCount == value) return;
            _lowStockAlertCount = value;
            NotifyAlertCountChanged();
        }
    }

    /// <summary>Raised when the selected warehouse changes.</summary>
    public event Func<Task>? OnWarehouseChanged;

    /// <summary>Raised when the low-stock alert count is updated.</summary>
    public event Func<Task>? OnAlertCountChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Coast"),
        ("WH-003", "Warehouse C — West Coast"),
        ("WH-004", "Warehouse D — Returns Processing"),
    };

    private void NotifyWarehouseChanged()
    {
        OnWarehouseChanged?.Invoke();
    }

    private void NotifyAlertCountChanged()
    {
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

namespace sv_7e2d95a6516c4ccface21825bec27c1c.Services;

/// <summary>
/// Simulates a database query for low-stock items in a given warehouse.
/// Registered as scoped so each circuit gets its own Random instance.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    /// <summary>
    /// Returns the count of items below minimum stock levels for the given warehouse.
    /// Simulates an async database call with a short delay.
    /// </summary>
    public async Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate I/O latency
        await Task.Delay(150);
        return _random.Next(0, 16); // 0–15 inclusive
    }
}

@rendermode InteractiveServer
@using sv_7e2d95a6516c4ccface21825bec27c1c.Services
@inject WarehouseStateService State
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="form-label mb-0 text-nowrap fw-semibold" for="warehouse-select">
        🏭 Site:
    </label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@State.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += HandleStateChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            State.CurrentWarehouseId = newId;
        }
        await Task.CompletedTask;
    }

    private async Task HandleStateChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        State.OnWarehouseChanged -= HandleStateChanged;
    }
}

@rendermode InteractiveServer
@using sv_7e2d95a6516c4ccface21825bec27c1c.Services
@inject WarehouseStateService State
@implements IDisposable

<span class="badge @BadgeClass rounded-pill ms-2" title="Low-stock alerts for @State.CurrentWarehouseId">
    @State.LowStockAlertCount
</span>

@code {
    private string BadgeClass => State.LowStockAlertCount switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        State.OnAlertCountChanged += HandleAlertCountChanged;
        State.OnWarehouseChanged += HandleAlertCountChanged;
    }

    private async Task HandleAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        State.OnAlertCountChanged -= HandleAlertCountChanged;
        State.OnWarehouseChanged -= HandleAlertCountChanged;
    }
}

