namespace sv_7e2d95a6516c4ccface21825bec27c1c.Services;

/// <summary>
/// Simulates a database query for low-stock items in a given warehouse.
/// Registered as scoped so each circuit gets its own Random instance.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    /// <summary>
    /// Returns the count of items below minimum stock levels for the given warehouse.
    /// Simulates an async database call with a short delay.
    /// </summary>
    public async Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate I/O latency
        await Task.Delay(150);
        return _random.Next(0, 16); // 0–15 inclusive
    }
}

