@page "/dashboard"
@rendermode InteractiveServer
@using sv_7e2d95a6516c4ccface21825bec27c1c.Services
@inject WarehouseStateService State
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>📦 Warehouse Dashboard</h1>
<p class="text-muted">
    Viewing: <strong>@CurrentWarehouseName</strong>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @AlertCardClass">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-3 fw-bold">@State.LowStockAlertCount</p>
                <p class="card-text text-muted">
                    Items below minimum levels
                </p>
                @if (_isPolling)
                {
                    <span class="badge bg-info">
                        <span class="spinner-grow spinner-grow-sm" role="status"></span>
                        Live — refreshing every 10s
                    </span>
                }
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Activity Log</h5>
                <ul class="list-group list-group-flush" style="max-height: 300px; overflow-y: auto;">
                    @foreach (var entry in _activityLog)
                    {
                        <li class="list-group-item small">@entry</li>
                    }
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private readonly List<string> _activityLog = new();

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == State.CurrentWarehouseId).Name
        ?? State.CurrentWarehouseId;

    private string AlertCardClass => State.LowStockAlertCount switch
    {
        0 => "border-success",
        <= 5 => "border-warning",
        _ => "border-danger"
    };

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += HandleWarehouseChanged;
        State.OnAlertCountChanged += HandleAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await StartPollingAsync();
        }
    }

    private async Task StartPollingAsync()
    {
        StopPolling();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _isPolling = true;

        // Fetch immediately on start
        await PollAlertCountAsync();

        _ = Task.Run(async () =>
        {
            try
            {
                while (await _timer.WaitForNextTickAsync(_cts.Token))
                {
                    await InvokeAsync(async () =>
                    {
                        await PollAlertCountAsync();
                    });
                }
            }
            catch (OperationCanceledException) { }
        });

        StateHasChanged();
    }

    private async Task PollAlertCountAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(State.CurrentWarehouseId);
        var timestamp = DateTime.Now.ToString("HH:mm:ss");

        _activityLog.Insert(0,
            $"[{timestamp}] Polled {State.CurrentWarehouseId}: {count} low-stock item(s)");

        if (_activityLog.Count > 50)
            _activityLog.RemoveRange(50, _activityLog.Count - 50);

        // Update shared state — this fires OnAlertCountChanged, notifying all subscribers
        State.LowStockAlertCount = count;
        StateHasChanged();
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(async () =>
        {
            _activityLog.Insert(0,
                $"[{DateTime.Now:HH:mm:ss}] Switched to {State.CurrentWarehouseId}");
            // Immediately poll for the new warehouse
            await PollAlertCountAsync();
        });
    }

    private async Task HandleAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
        _isPolling = false;
    }

    public void Dispose()
    {
        StopPolling();
        State.OnWarehouseChanged -= HandleWarehouseChanged;
        State.OnAlertCountChanged -= HandleAlertCountChanged;
    }
}

